var player = GetPlayer();

// Получаем значения переменных из Storyline
var dateEnd = player.GetVar("Date_End");  // Например: "30.08.2024" или "30:08:2024"
var timeEnd = player.GetVar("Time_End");  // Например: "10:26:25"
var dateUnblock = player.GetVar("Date_Unblock");  // Например: "13.09.2024 10:26:25" или "13:09:2024 10.26.25"

// Функция для преобразования строки даты и времени в объект Date
function parseDateTime(dateStr, timeStr) {
    // Заменяем любые двоеточия на точки в строке даты
    dateStr = dateStr.replace(/:/g, '.');
    
    // Заменяем любые точки на двоеточия в строке времени
    if (timeStr) {
        timeStr = timeStr.replace(/\./g, ':');
    } else {
        timeStr = "00:00:00"; // Если время не указано, устанавливаем 00:00:00
    }
    
    var partsDate = dateStr.split('.');
    var partsTime = timeStr.split(':');
    
    return new Date(partsDate[2], partsDate[1] - 1, partsDate[0], partsTime[0], partsTime[1], partsTime[2]);
}

// Преобразуем строки в объекты Date
var currentDateTime = new Date();
var dateEndObj = parseDateTime(dateEnd, timeEnd);
var dateUnblockObj = parseDateTime(dateUnblock.split(' ')[0], dateUnblock.split(' ')[1]);

// Логи текущей даты и времени
console.log("Текущая дата и время: " + currentDateTime.toString());
console.log("Date_End и Time_End как объект Date: " + dateEndObj.toString());
console.log("Date_Unblock как объект Date: " + dateUnblockObj.toString());

// Логика проверки условий
if (currentDateTime > dateEndObj) {
    player.SetVar("FinalView", 100);
    console.log("Условие выполнено: текущая дата и время больше, чем Date_End и Time_End. FinalView установлен на 100.");
} else {
    console.log("Условие не выполнено: текущая дата и время не больше, чем Date_End и Time_End.");
}

if (currentDateTime > dateUnblockObj) {
    player.SetVar("FinalView", 200);
    console.log("Условие выполнено: текущая дата и время больше, чем Date_Unblock. FinalView установлен на 200.");
} else {
    console.log("Условие не выполнено: текущая дата и время не больше, чем Date_Unblock.");
}

(function() {
    if (window.TabMonitorInstance) {
        return;
    }
    window.TabMonitorInstance = true;

    const channel = new BroadcastChannel('course_tabs_channel');

    if (!document.querySelector('#tab-monitor-styles')) {
        const style = document.createElement('style');
        style.id = 'tab-monitor-styles';
        style.textContent = `
            .duplicate-warning-modal {
                display: none;
                position: fixed;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                background: white;
                padding: 24px;
                border-radius: 12px;
                box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
                z-index: 10000;
                width: 90%;
                max-width: 600px;
                text-align: left;
                font-family: Arial, sans-serif;
            }
            .duplicate-warning-modal.show {
                display: block;
            }
            .duplicate-warning-overlay {
                display: none;
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0, 0, 0, 0.5);
                z-index: 9999;
            }
            .duplicate-warning-overlay.show {
                display: block;
            }
            .warning-content {
                color: #333;
                font-size: 16px;
                line-height: 1.5;
                margin: 0;
            }
        `;
        document.head.appendChild(style);
    }

    if (!document.querySelector('.duplicate-warning-modal')) {
        const modal = document.createElement('div');
        modal.className = 'duplicate-warning-modal';
        modal.innerHTML = `
            <p class="warning-content">
                Сертификационный тест был открыт в нескольких вкладках. Это привело к частичной потере прогресса. Закройте все вкладки и зайдите в тест заново.
            </p>
        `;

        const overlay = document.createElement('div');
        overlay.className = 'duplicate-warning-overlay';

        document.body.appendChild(overlay);
        document.body.appendChild(modal);
    }

    function showDuplicateWarning() {
        const modal = document.querySelector('.duplicate-warning-modal');
        const overlay = document.querySelector('.duplicate-warning-overlay');
        if (modal && overlay) {
            modal.classList.add('show');
            overlay.classList.add('show');
        }
    }

    const tabId = Date.now().toString(36) + Math.random().toString(36).substr(2);
    channel.postMessage({ type: 'tab_opened', id: tabId });

    const activeTabs = new Set();
    activeTabs.add(tabId);

    let warningVisible = false;

    function checkDuplicateTabs() {
        if (activeTabs.size > 1 && !warningVisible) {
            showDuplicateWarning();
            warningVisible = true;
        }
        // После показа уведомления оно остается видимым, даже если дублированная вкладка закрыта
    }

    channel.onmessage = (event) => {
        const { type, id } = event.data;

        if (type === 'tab_opened') {
            activeTabs.add(id);
            channel.postMessage({ type: 'tab_active', id: tabId });
            checkDuplicateTabs();
        } else if (type === 'tab_active') {
            activeTabs.add(id);
            checkDuplicateTabs();
        } else if (type === 'tab_closed') {
            activeTabs.delete(id);
            // Не скрываем уведомление, даже если осталось только одна вкладка
        }
    };

    window.addEventListener('beforeunload', () => {
        channel.postMessage({ type: 'tab_closed', id: tabId });
        channel.close();
    });

    setInterval(checkDuplicateTabs, 1000);
})();

// Получаем доступ к API SCORM 2004
var player = GetPlayer(); // получение доступа к плееру (если понадобится позже)

var scormAPI = window.parent.API_1484_11 || window.API_1484_11; 

if (scormAPI) {
    var result = scormAPI.Commit("");
    console.log("Commit успешно выполнен. Результат:", result);
} else {
    console.error("SCORM 2004 API не найден");
}
